<template><div><Alert show-icon>材料按商户主体核验。受保护字段留空表示保留已有内容；新的证件或账户需要重新填写完整资料。</Alert><RecordDetail v-if="protectedFields" :value="{protectedFields}"/><FieldsForm v-model="form" :fields="baseFields" :disabled="disabled"/><Select v-model="form.licenseFileId" :disabled="disabled" clearable placeholder="选择已批准营业执照附件"><Option v-for="item in licenses" :key="item.id" :value="item.id">{{item.label}}</Option></Select><Button v-if="form.licenseFileId" @click="$emit('preview',form.licenseFileId)">预览营业执照</Button><h3>法定代表人证件</h3><ChannelDocument v-model="form.legalId" :receipt-scope="receiptScope+':legal'" :disabled="disabled" @preview="$emit('preview',$event)"/><h3>超级管理员联系资料</h3><FieldsForm v-model="form.contact" :fields="contactFields" :disabled="disabled"/><ChannelDocument v-if="form.contact.type==='AGENT'" :value="form.contact.identity||{}" :receipt-scope="receiptScope+':contact'" :disabled="disabled" @input="form.contact={...form.contact,identity:$event}" @preview="$emit('preview',$event)"/><FileField v-model="form.contact.authorizationFileId" :receipt-key="receiptScope+':authorization'" purpose="CHANNEL" title="代理授权文件" :disabled="disabled" @preview="$emit('preview',$event)"/><h3>结算账户资料</h3><FieldsForm v-model="form.account" :fields="accountFields" :disabled="disabled"/><h3>经营场景</h3><FieldsForm v-model="form.sales" :fields="salesFields" :disabled="disabled"/><FileField v-model="form.sales.qrFileId" :receipt-key="receiptScope+':salesQr'" purpose="CHANNEL" title="经营场景二维码" images-only :disabled="disabled" @preview="$emit('preview',$event)"/><h3>受益所有人</h3><Checkbox v-model="form.soleBeneficialOwner" :disabled="disabled">法定代表人是唯一受益所有人</Checkbox><template v-if="!form.soleBeneficialOwner"><Checkbox v-model="replaceOwners" :disabled="disabled">本次填写或替换受益所有人资料</Checkbox><template v-if="replaceOwners"><section v-for="(owner,index) in owners" :key="index"><h4>受益所有人 {{index+1}}</h4><ChannelDocument v-model="owners[index]" :receipt-scope="receiptScope+':beneficial:'+index" :disabled="disabled" @preview="$emit('preview',$event)"/><Button :disabled="disabled" @click="owners.splice(index,1)">移除此项</Button></section><Button :disabled="disabled||owners.length>=4" @click="owners.push({})">新增受益所有人</Button></template></template><FileField v-model="form.specialQualificationFileIds" :receipt-key="receiptScope+':special'" multiple :maximum="5" purpose="CHANNEL" title="专项资质附件" :disabled="disabled" @preview="$emit('preview',$event)"/><FileField v-model="form.additionFileIds" :receipt-key="receiptScope+':addition'" multiple :maximum="15" purpose="CHANNEL" title="补充附件" :disabled="disabled" @preview="$emit('preview',$event)"/><FieldsForm v-model="note" :fields="[{key:'reason',label:'本次材料变更原因',type:'textarea',required:true,max:500}]" :disabled="disabled"/><Button type="primary" :disabled="disabled" @click="save">保存材料版本</Button></div></template>
<script>import FieldsForm from './FieldsForm';import ChannelDocument from './ChannelDocument';import FileField from './FileField';import RecordDetail from './RecordDetail';
function compact(value){if(Array.isArray(value))return value.map(compact);if(value&&typeof value==='object'){const result={};Object.keys(value).forEach(k=>{if(value[k]!==''&&value[k]!==undefined)result[k]=compact(value[k]);});if(result.longTerm)result.validThrough=null;return result;}return value;}
export default {components:{FieldsForm,ChannelDocument,FileField,RecordDetail},props:{value:Object,receiptScope:{type:String,required:true},protectedFields:Object,licenses:{type:Array,default:()=>[]},disabled:Boolean},data(){const old=JSON.parse(JSON.stringify(this.value||{}));delete old.beneficialOwners;return {form:{schemaVersion:'WX_ECOMMERCE_S1_20260509',legalId:{},contact:{},account:{},sales:{},specialQualificationFileIds:[],additionFileIds:[],...old},note:{reason:''},replaceOwners:false,owners:[],baseFields:[{key:'authorizationBasis',label:'材料使用授权依据',type:'textarea',required:true,max:500},{key:'shortName',label:'商户简称',required:true,max:64},{key:'settlementId',label:'获准结算规则编号',type:'integer',required:true,min:1,max:2147483647},{key:'industryName',label:'获准行业名称',required:true,max:200},{key:'additionDescription',label:'补充说明',type:'textarea',max:512}],contactFields:[{key:'type',label:'联系人身份',type:'select',required:true,options:[{value:'LEGAL',label:'法定代表人'},{value:'AGENT',label:'代理人'}]},{key:'name',label:'联系人姓名',required:true,max:100},{key:'phone',label:'联系电话',max:20,help:'已有受保护号码留空保留。'}],accountFields:[{key:'type',label:'账户类型',type:'select',required:true,options:[{value:'PUBLIC',label:'对公账户'},{value:'PRIVATE',label:'法定代表人个人账户'}]},{key:'name',label:'开户名称',required:true,max:128},{key:'number',label:'银行账号',max:128,help:'已有受保护账号留空保留。'},{key:'bankCode',label:'开户银行渠道编码',required:true,max:10,help:'是否需要支行由服务端渠道目录校验。'},{key:'bankBranchId',label:'支行联行号',max:64},{key:'bankName',label:'完整支行名称',max:128}],salesFields:[{key:'name',label:'经营场景名称',required:true,max:256},{key:'url',label:'经营场景链接',max:1024},{key:'merchantMiniAppId',label:'商户小程序 AppID',max:256}]};},methods:{save(){let materials=compact(this.form);if(materials.soleBeneficialOwner)materials.beneficialOwners=[];else if(this.replaceOwners)materials.beneficialOwners=this.owners.map(compact);this.$emit('save',{materials,reason:this.note.reason});}}};
</script><style scoped>h3{padding:20px 0 12px;border-bottom:1px solid #e8eaec;margin-bottom:16px}h4{padding:16px 0}.ivu-checkbox-wrapper{padding:12px 0}.ivu-btn{margin:12px 8px 12px 0}section{border:1px solid #ddd;padding:14px;margin:14px 0}</style>
